package cn.binbin.crm;
import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.util.*;import javax.net.ssl.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Component;
/** Pin each connection to a freshly validated address; redirects are never followed. */
@Component
public class WebhookTransport {
 private final boolean isolated;private final String db,prefix;
 public WebhookTransport(@Value("${CRM_ISOLATED_ACCEPTANCE:false}") boolean isolated,@Value("${CRM_DB_URL:}") String db,@Value("${CRM_S3_PREFIX:}") String prefix){this.isolated=isolated;this.db=db;this.prefix=prefix;}
 boolean testDestination(URI uri){return isolated&&db.contains("crm_acceptance")&&prefix.startsWith("p3-acceptance-")&&"http".equals(uri.getScheme())&&"crm-p0-verification.railway.internal".equals(uri.getHost())&&uri.getPort()==2526;}
 URI uri(String input){try{URI u=URI.create(input);if(input.length()>2048||u.getRawUserInfo()!=null||u.getRawFragment()!=null||u.getHost()==null||u.getHost().contains("%")||!("https".equals(u.getScheme())&&(u.getPort()==-1||u.getPort()==443)||testDestination(u)))throw ApiError.bad("Webhook 需使用公网 HTTPS 443 地址，不接受账户信息或片段");if(u.getRawPath()!=null&&(u.getRawPath().contains("\r")||u.getRawPath().contains("\n")))throw ApiError.bad("Webhook 地址无效");return u;}catch(IllegalArgumentException e){throw ApiError.bad("Webhook 地址无效");}}
 static boolean publicAddress(InetAddress a){byte[] v=a.getAddress();if(a.isAnyLocalAddress()||a.isLoopbackAddress()||a.isLinkLocalAddress()||a.isSiteLocalAddress()||a.isMulticastAddress())return false;if(v.length==4){int x=v[0]&255,y=v[1]&255,z=v[2]&255;return !(x==0||x==10||x==127||x>=224||x==100&&y>=64&&y<=127||x==169&&y==254||x==172&&y>=16&&y<=31||x==192&&(y==168||y==0||y==2||y==88&&z==99)||x==198&&(y==18||y==19||y==51&&z==100)||x==203&&y==0&&z==113);}if(v.length==16){int x=v[0]&255,y=v[1]&255;return x>=0x20&&x<=0x3f&&!(x==0x20&&y==2)&&!(x==0x20&&y==1&&(v[2]&255)==0x0d&&(v[3]&255)==0xb8)&&!(x==0x20&&y==1&&(v[2]&255)==0); }return false;}
 InetAddress[] addresses(URI u)throws IOException{var all=InetAddress.getAllByName(u.getHost());if(all.length==0)throw new IOException("DNS_FAILED");if(!testDestination(u))for(var a:all)if(!publicAddress(a))throw new IOException("DESTINATION_BLOCKED");return all;}
 void validate(String input){URI u=uri(input);try{addresses(u);}catch(IOException e){throw ApiError.bad("Webhook 域名需解析为允许的公网地址");}}
 int post(String destination,String body,Map<String,String> headers)throws IOException{URI u=uri(destination);InetAddress ip=addresses(u)[0];int port=testDestination(u)?2526:443;Socket raw=new Socket();try{raw.connect(new InetSocketAddress(ip,port),4000);raw.setSoTimeout(5000);Socket socket=raw;if(!testDestination(u)){var tls=(SSLSocket)((SSLSocketFactory)SSLSocketFactory.getDefault()).createSocket(raw,u.getHost(),443,true);var p=tls.getSSLParameters();p.setEndpointIdentificationAlgorithm("HTTPS");p.setServerNames(List.of(new SNIHostName(u.getHost())));tls.setSSLParameters(p);tls.startHandshake();socket=tls;}byte[] bytes=body.getBytes(StandardCharsets.UTF_8);String path=u.getRawPath();if(path==null||path.isEmpty())path="/";if(u.getRawQuery()!=null)path+="?"+u.getRawQuery();String host=u.getHost().contains(":")?"["+u.getHost()+"]":u.getHost();if(port!=443)host+=":"+port;var head=new StringBuilder("POST ").append(path).append(" HTTP/1.1\r\nHost: ").append(host).append("\r\nContent-Type: application/json\r\nConnection: close\r\nContent-Length: ").append(bytes.length).append("\r\n");headers.forEach((k,v)->head.append(k).append(": ").append(v).append("\r\n"));head.append("\r\n");var out=socket.getOutputStream();out.write(head.toString().getBytes(StandardCharsets.US_ASCII));out.write(bytes);out.flush();var in=socket.getInputStream();var buffer=new ByteArrayOutputStream();int previous=0,count=0;while(buffer.size()<16384){int c=in.read();if(c<0)break;buffer.write(c);if(previous=='\r'&&c=='\n')count++;else if(c!='\r')count=0;previous=c;if(count==2)break;}String response=buffer.toString(StandardCharsets.US_ASCII);String line=response.split("\r\n",2)[0];if(!line.matches("HTTP/1\\.[01] [1-5][0-9]{2}( .*)?"))throw new IOException("INVALID_RESPONSE");return Integer.parseInt(line.substring(9,12));}finally{raw.close();}}
}
